from typing import Type, Any
from rclpy.node import Node as ROS2BaseNode
from ..logger.logger import logger


class ROS2Publisher:
    def __init__(
        self,
        node: ROS2BaseNode,
        msg_type: Type,
        topic: str,
        qos_profile: int = 10,
        **kwargs
    ):
        """
        创建ROS2发布者

        Args:
            node: ROS2BaseNode实例
            msg_type: 消息类型
            topic: 话题名称
            qos_profile: QoS配置
            **kwargs: 其他参数传递给create_publisher
        """
        self._node = node
        self._msg_type = msg_type
        self._topic = topic
        self._publisher = node.create_publisher(msg_type, topic, qos_profile, **kwargs)

    def publish(self, msg: Any):
        """
        发布消息

        Args:
            msg: 要发布的消息对象
        """
        self._publisher.publish(msg)

    @property
    def topic(self) -> str:
        """获取话题名称"""
        return self._topic

    @property
    def msg_type(self) -> Type:
        """获取消息类型"""
        return self._msg_type

    def destroy(self):
        """销毁发布者"""
        self._node.destroy_publisher(self._publisher)
